if("PerformanceObserver"in window)try{new PerformanceObserver(r=>{for(const e of r.getEntries())window.__LOVEQUIZ_DEBUG_PERF__&&console.log(`[CWV] ${e.name}: ${Math.round(e.startTime)}ms`,e)}).observe({entryTypes:["largest-contentful-paint","first-input","layout-shift"]})}catch{}document.addEventListener("DOMContentLoaded",()=>{const n=["quiz.html","blog.html","tools.html"],r=new Set;document.querySelectorAll("a[href]").forEach(e=>{const t=e.getAttribute("href");t&&n.includes(t)&&e.addEventListener("mouseenter",()=>{if(!r.has(t)){r.add(t);const o=document.createElement("link");o.rel="prefetch",o.href=t,document.head.appendChild(o)}},{passive:!0})})});
